const texto = $json.content?.parts?.[0]?.text;

if (!texto) {
  throw new Error(
    "O Gemini não retornou texto no caminho esperado."
  );
}

// Remove cercas Markdown, caso o modelo as inclua.
const textoLimpo = texto
  .replace(/^```(?:json)?\s*/i, "")
  .replace(/\s*```$/, "")
  .trim();

let resultado;

try {
  resultado = JSON.parse(textoLimpo);
} catch (erro) {
  throw new Error(
    "A resposta do Gemini não contém um JSON válido."
  );
}

// Confere se os três campos obrigatórios existem.
const { categoria, prioridade, resposta } = resultado;

const categoriasPermitidas = [
  "Abertura de empresa",
  "Consultoria",
  "Produtos digitais",
  "Outros serviços"
];

const prioridadesPermitidas = [
  "Alta",
  "Média",
  "Baixa"
];

if (
  !categoriasPermitidas.includes(categoria) ||
  !prioridadesPermitidas.includes(prioridade) ||
  typeof resposta !== "string" ||
  !resposta.trim()
) {
  throw new Error(
    "O Gemini retornou campos ausentes ou valores inválidos."
  );
}

// Entrega ao próximo nó um objeto JSON limpo.
return {
  json: {
    categoria,
    prioridade,
    resposta
  }
};
